#include <bits/stdc++.h>
using namespace std;
static const int N=35; static const int MINDEG=11,MAXDEG=17;
uint64_t FULL=(1ULL<<N)-1, adjm[N]; int deg0[N];
vector<uint64_t> TRI,I3,I4,I5;
struct UOut{vector<uint64_t>d;long long nodes=0;};
vector<string> read_exoo(const string&p){ifstream f(p);vector<string>L;string s;while(f>>s)if(!s.empty())L.push_back(s);if(L.size()!=35)throw runtime_error("need 35 rows");vector<string>r(35,string(35,'0'));for(int i=0;i<35;i++)for(int j=0;j<35;j++){if(i==j)r[i][j]='0';else r[i][j]=(L[i][j]=='0'?'1':'0');}return r;}
vector<uint64_t> setsK(int k,bool edge){vector<uint64_t>out;vector<int>v(k);function<void(int,int)>rec=[&](int pos,int st){if(pos==k){for(int i=0;i<k;i++)for(int j=i+1;j<k;j++)if(bool((adjm[v[i]]>>v[j])&1)!=edge)return;uint64_t m=0;for(int x:v)m|=1ULL<<x;out.push_back(m);return;}for(int x=st;x<=N-(k-pos);x++){v[pos]=x;rec(pos+1,x+1);}};rec(0,0);return out;}
bool independent(uint64_t m){uint64_t z=m;while(z){int v=__builtin_ctzll(z);z&=z-1;if(adjm[v]&z)return false;}return true;}
UOut domains(uint64_t del){vector<uint64_t>tri,i5;int occ[N]={};for(auto m:TRI)if(!(m&del)){tri.push_back(m);uint64_t z=m;while(z){int v=__builtin_ctzll(z);z&=z-1;occ[v]++;}}for(auto m:I5)if(!(m&del)){i5.push_back(m);uint64_t z=m;while(z){int v=__builtin_ctzll(z);z&=z-1;occ[v]++;}}uint64_t ALL=FULL^del;UOut o;
 function<bool(uint64_t&,uint64_t&)>prop=[&](uint64_t&one,uint64_t&zero){while(1){if(one&zero)return false;int c=__builtin_popcountll(one),un=__builtin_popcountll(ALL&~(one|zero));if(c>17||c+un<9)return false;bool ch=false;if(c==17){uint64_t u=ALL&~(one|zero);if(u){zero|=u;ch=true;}}if(c+un==9){uint64_t u=ALL&~(one|zero);if(u){one|=u;ch=true;}}for(auto m:tri){int x=__builtin_popcountll(one&m);if(x>=3)return false;if(x==2){uint64_t u=m&~(one|zero);if(u&&!(u&(u-1))){zero|=u;ch=true;}}}for(auto m:i5){int x=__builtin_popcountll(zero&m);if(x>=5)return false;if(x==4){uint64_t u=m&~(one|zero);if(u&&!(u&(u-1))){one|=u;ch=true;}}}if(!ch)return true;}};
 function<void(uint64_t,uint64_t)>dfs=[&](uint64_t one,uint64_t zero){o.nodes++;if(!prop(one,zero))return;if(((one|zero)&ALL)==ALL){o.d.push_back(one);return;}uint64_t U=ALL&~(one|zero);int best=-1,bs=-1;while(U){int v=__builtin_ctzll(U);U&=U-1;if(occ[v]>bs){bs=occ[v];best=v;}}dfs(one|1ULL<<best,zero);dfs(one,zero|1ULL<<best);};dfs(0,del);return o;}
struct Res{bool sat=false;int dom=0;long long nodes=0,checked=0;int a,b;array<uint64_t,3>M{};int h=0;};
Res solvepair(int a,int b){uint64_t del=(1ULL<<a)|(1ULL<<b);auto u=domains(del);Res R;R.dom=u.d.size();R.nodes=u.nodes;R.a=a;R.b=b;vector<uint64_t>i3,i4;for(auto m:I3)if(!(m&del))i3.push_back(m);for(auto m:I4)if(!(m&del))i4.push_back(m);int coredeg[N];for(int v=0;v<N;v++)if(!(del>>v&1))coredeg[v]=deg0[v]-((adjm[v]>>a)&1)-((adjm[v]>>b)&1);
 int M=u.d.size();vector<vector<unsigned char>>st(M,vector<unsigned char>(M));for(int i=0;i<M;i++)for(int j=0;j<M;j++){bool eok=independent(u.d[i]&u.d[j]);bool n0=true;uint64_t uni=u.d[i]|u.d[j];for(auto s:i4)if(!(uni&s)){n0=false;break;}st[i][j]=(n0?1:0)|(eok?2:0);}int P[3][2]={{0,1},{0,2},{1,2}};
 for(int i=0;i<M;i++)for(int j=0;j<M;j++)for(int k=0;k<M;k++){array<uint64_t,3>X={u.d[i],u.d[j],u.d[k]};bool cok=true;for(int v=0;v<N;v++)if(!(del>>v&1)){int d=coredeg[v]+((X[0]>>v)&1)+((X[1]>>v)&1)+((X[2]>>v)&1);if(d<11||d>17){cok=false;break;}}if(!cok)continue;int idx[3]={i,j,k};for(int h=0;h<8;h++){R.checked++;int nd[3]={};bool ok=true;for(int p=0;p<3;p++){int x=P[p][0],y=P[p][1],e=(h>>p)&1;if(!(st[idx[x]][idx[y]]&(e?2:1))){ok=false;break;}if(e){nd[x]++;nd[y]++;}}if(!ok)continue;for(int q=0;q<3;q++){int d=__builtin_popcountll(X[q])+nd[q];if(d<11||d>17){ok=false;break;}}if(!ok)continue;if(h==7&&(X[0]&X[1]&X[2]))continue;if(h==0){uint64_t uni=X[0]|X[1]|X[2];for(auto s:i3)if(!(uni&s)){ok=false;break;}}if(!ok)continue;R.sat=true;R.M=X;R.h=h;return R;}}
 return R;}
vector<string> reconstruct(const vector<string>&r,const Res&z){vector<int>core;for(int v=0;v<N;v++)if(v!=z.a&&v!=z.b)core.push_back(v);vector<string>o(36,string(36,'0'));for(int i=0;i<33;i++)for(int j=0;j<33;j++)o[i][j]=r[core[i]][core[j]];for(int q=0;q<3;q++)for(int i=0;i<33;i++)if((z.M[q]>>core[i])&1)o[33+q][i]=o[i][33+q]='1';int P[3][2]={{0,1},{0,2},{1,2}};for(int p=0;p<3;p++)if(z.h>>p&1)o[33+P[p][0]][33+P[p][1]]=o[33+P[p][1]][33+P[p][0]]='1';return o;}
bool verify(const vector<string>&r){int n=r.size();for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)for(int c=b+1;c<n;c++)for(int d=c+1;d<n;d++){int v[4]={a,b,c,d};bool bad=1;for(int i=0;i<4&&bad;i++)for(int j=i+1;j<4;j++)if(r[v[i]][v[j]]!='1'){bad=0;break;}if(bad)return false;}for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)for(int c=b+1;c<n;c++)for(int d=c+1;d<n;d++)for(int e=d+1;e<n;e++)for(int f=e+1;f<n;f++){int v[6]={a,b,c,d,e,f};bool bad=1;for(int i=0;i<6&&bad;i++)for(int j=i+1;j<6;j++)if(r[v[i]][v[j]]!='0'){bad=0;break;}if(bad)return false;}return true;}
int main(int argc,char**argv){if(argc<3){cerr<<"usage: three_regrow35 core.txt summary.json [candidate.json] [start end]\n";return 64;}auto r=read_exoo(argv[1]);for(int i=0;i<N;i++){uint64_t m=0;for(int j=0;j<N;j++)if(r[i][j]=='1')m|=1ULL<<j;adjm[i]=m;deg0[i]=__builtin_popcountll(m);}TRI=setsK(3,1);I3=setsK(3,0);I4=setsK(4,0);I5=setsK(5,0);if(!verify(r)){cerr<<"source not good35\n";return 2;}vector<pair<int,int>>pairs;for(int i=0;i<N;i++)for(int j=i+1;j<N;j++)pairs.push_back({i,j});int st=argc>=6?atoi(argv[4]):0,en=argc>=6?atoi(argv[5]):pairs.size();if(st<0||en>(int)pairs.size()||st>en)return 64;vector<Res>rows;Res hit;bool found=false;map<int,int>hist;int mx=0;for(int q=st;q<en;q++){auto [a,b]=pairs[q];auto z=solvepair(a,b);rows.push_back(z);hist[z.dom]++;mx=max(mx,z.dom);if(z.sat){hit=z;found=true;break;}if((q-st+1)%100==0)cerr<<"PROGRESS "<<(q-st+1)<<" maxdom="<<mx<<"\n";}
 ofstream out(argv[2]);out<<"{\n  \"campaign\":\"exact-three-vertex-regrow-of-one-published-35-core\",\n  \"ordinal_range\":["<<st<<","<<en<<"],\n  \"deleted_33_cores_completed\":"<<rows.size()<<",\n  \"all_unsat\":"<<((!found&&rows.size()==size_t(en-st))?"true":"false")<<",\n  \"found\":"<<(found?"true":"false")<<",\n  \"max_domain_count\":"<<mx<<",\n  \"domain_count_histogram\":{";bool first=1;for(auto [k,v]:hist){if(!first)out<<',';first=0;out<<'\"'<<k<<"\":"<<v;}out<<"},\n  \"results\":[\n";for(size_t i=0;i<rows.size();i++){auto &z=rows[i];out<<"    {\"deleted_vertices\":["<<z.a<<","<<z.b<<"],\"status\":\""<<(z.sat?"SAT":"UNSAT")<<"\",\"domain_count\":"<<z.dom<<",\"unary_dfs_nodes\":"<<z.nodes<<",\"checked_h_states\":"<<z.checked<<"}"<<(i+1<rows.size()?",":"")<<"\n";}out<<"  ]\n}\n";out.close();if(found){auto rr=reconstruct(r,hit);if(!verify(rr))return 3;for(auto&s:rr){int d=count(s.begin(),s.end(),'1');if(d<11||d>17)return 4;}if(argc<4)return 5;ofstream c(argv[3]);c<<"{\"adjacency\":[";for(int i=0;i<36;i++){if(i)c<<',';c<<'\"'<<rr[i]<<'\"';}c<<"]}\n";cerr<<"FOUND deleted="<<hit.a<<","<<hit.b<<" edges=";long long E=0;for(auto&s:rr)E+=count(s.begin(),s.end(),'1');cerr<<E/2<<"\n";return 10;}cerr<<"DONE range="<<st<<","<<en<<" cores="<<rows.size()<<" maxdom="<<mx<<"\n";return 20;}
